// Flatten LESSONS into queue of teaching-unit bundles (attaching lessonHeader & sectionHeaders cleanly)
const unitQueue = [];
let unitCounter = 0;
for (const lesson of LESSONS) {
  let pendingLessonHdr = {
    lessonNo: lesson.lessonNo,
    title: lesson.lessonTitle,
    hours: lesson.hours,
    sPage: lesson.sPage,
    tPage: lesson.tPage,
  };
  let pendingSections = [];
  for (const item of lesson.items) {
    if (item.type === "section") {
      pendingSections.push(item);
    } else {
      unitCounter++;
      unitQueue.push({
        unitIndex: unitCounter,
        lessonNo: lesson.lessonNo,
        lessonHeader: pendingLessonHdr,
        sectionHeaders: pendingSections,
        unit: item,
      });
      pendingLessonHdr = null;
      pendingSections = [];
    }
  }
}

if (unitQueue.length !== 222) {
  throw new Error("Expected 222 PDF teaching units, got " + unitQueue.length);
}

